//! ⌨️ The real mounted Layout typing edit retains its original source while prior transactions publish.
use super::*;

#[semio_framework_async_macros::async_test]
async fn mounted_typing_edits_publish_previous_transaction_and_keep_latest_preview(){
 let fixture:Value=serde_json::from_str(include_str!("../../../../../../../../../../../../../🧰️framework/🛍️products/💻️os/🔨️modules/🔌️plugin/🛠️tool-machine/⌨️typing/✍️edit/🧪️fixtures/🔣️.json")).unwrap();let action=fixture["action"].as_str().unwrap();let buffer=fixture["buffer"].as_str().unwrap();let first=fixture["deliveries"][0]["name"].as_str().unwrap();let second=fixture["deliveries"][1]["name"].as_str().unwrap();
 let mut app=layout_app_with_registry().await;let baseline=app.0.snapshot().unwrap().name.clone();let source=app.1.cx().original_recipient_identity();let decoder=app.1.cx().native_receiving_identity();let operation=app.1.cx().operation();let generation=app.1.cx().generation();
 let delivered=act(&mut app,action,Some(DslValue::from(&serde_json::json!({"field":"name","value":first,"typing":buffer})))).await;let first_result=settle(&mut app,delivered).await;assert!(edit_rows(&first_result).is_empty());assert_eq!(app.0.snapshot().unwrap().name,baseline);assert_eq!(app.0.rendered_snapshot().name,first);
 let delivered=act(&mut app,action,Some(DslValue::from(&serde_json::json!({"field":"name","value":second,"typing":buffer})))).await;let second_result=settle(&mut app,delivered).await;assert_eq!(edit_rows(&second_result).len(),1);assert_eq!(app.0.snapshot().unwrap().name,first);assert_eq!(app.0.rendered_snapshot().name,second);
 let delivered=act(&mut app,action,Some(DslValue::from(&serde_json::json!({"typing":buffer,"typingCommit":"enter"})))).await;let committed=settle(&mut app,delivered).await;assert_eq!(edit_rows(&committed).len(),1);assert_ne!(edit_rows(&second_result)[0].transaction,edit_rows(&committed)[0].transaction);assert_eq!(app.0.snapshot().unwrap().name,second);assert_eq!(app.0.rendered_snapshot().name,second);
 assert_eq!(app.1.cx().original_recipient_identity(),source);assert_eq!(app.1.cx().native_receiving_identity(),decoder);assert_eq!(app.1.cx().operation(),operation);assert_eq!(app.1.cx().generation(),generation);assert!(app.0.maintenance_source_terminal_is_empty());
 println!("mounted-typing-edit={}",serde_json::json!({"firstPreview":first,"priorCommitted":first,"lastPreview":second,"finalCommitted":second,"firstRows":edit_rows(&first_result).len(),"priorRows":edit_rows(&second_result).len(),"finalRows":edit_rows(&committed).len(),"sameSource":true,"closed":app.0.maintenance_source_terminal_is_empty()}));app.close_fixture();
}

/// 🧺️ One-item original turns preserve the actual mutation backing and cancel only the unpublished replacement.
#[test]
fn original_typing_settlement_moves_actual_layout_leaves_and_keeps_cancelled_resident(){
 use semio_plugin_typing_edit::OriginalTypingSettlement;
 use semio_plugin_tool_run::tool_jobs_tool_machine::{TypingTag,ToolMachineRuntime};
 use semio_framework_tool_machine::{TypingLedger,TypingState};
 use semio_framework_value::{SharedUtf8,RetainedCloneGrant};
 use semio_framework_value::retirement::controlled::ControlledRetirement;
 use semio_framework_job::close_original_retained_step;
 type A=semio_plugin::EditorApp<LayoutPlayApp>;
 for cancel in [false,true]{
  let mut caller=artifact_app_laws::OriginalFixtureScope::admit();let mut ledger=TypingLedger::<LayoutMutation>::default();let mut clock_source=ToolMachineRuntime::<LayoutSnapshot,LayoutMutation,semio_plugin::NoConfig,semio_plugin::NoConfigMutation>::default();let metadata=window_meta(WINDOW);let base=[7;32];let unit=RetainedCloneGrant{maximum_items:1,..caller.cx().retained_grant()};let mut previous_pointer=std::ptr::null();let original_source=caller.cx().original_recipient_identity();let original_decoder=caller.cx().native_receiving_identity();
  for (index,name) in ["Typing First","Typing Second"].into_iter().enumerate(){
   let mut emit=semio_plugin::Emit::<LayoutMutation,semio_plugin::NoConfigMutation,semio_plugin::NoDraftMutation>::mutations(vec![LayoutMutation::RenameLayout(semio_s_artifact_layout_layout_mutations_content::rename_layout::RenameLayout{new_name:name.into()})]);
   let mut tag=Some(TypingTag{window:WINDOW.into(),tool:"s.layout.layout#patchDocument".into(),buffer:"layout-title".into()});let mut owner=None;let pointer=match &emit.artifact_mutations[0]{LayoutMutation::RenameLayout(value)=>value.new_name.as_ptr(),_=>unreachable!()};let input=emit.artifact_mutations.as_ptr();let receipt=caller.cx().retained_progress();
   assert!(!caller.cx().with_retained_loan(Default::default(),|same|OriginalTypingSettlement::<A>::admit(index as u64+1,&base,&metadata.actor,&mut emit,0,||(tag.take().unwrap(),clock_source.clock()),same,&mut owner)).unwrap());assert!(tag.is_some());assert!(owner.is_none());assert_eq!(emit.artifact_mutations.as_ptr(),input);assert_eq!(caller.cx().retained_progress(),receipt);
   for _ in 0..2{assert!(!caller.cx().with_retained_loan(unit,|same|OriginalTypingSettlement::<A>::admit(index as u64+1,&base,&metadata.actor,&mut emit,0,||(tag.take().unwrap(),clock_source.clock()),same,&mut owner)).unwrap());assert!(tag.is_some());assert_eq!(emit.artifact_mutations.as_ptr(),input);}
   let quote=OriginalTypingSettlement::<A>::capture_demands(&metadata.actor,0).unwrap();let frame=SharedUtf8::admission_demand().capacity_bytes;let before=caller.cx().retained_progress();let denied=RetainedCloneGrant{maximum_capacity_bytes:quote.capacity_bytes-1,..unit};
   assert!(!actor_admission_turn(caller.cx(),|cx|cx.with_retained_loan(denied,|same|OriginalTypingSettlement::<A>::admit(index as u64+1,&base,&metadata.actor,&mut emit,0,||(tag.take().unwrap(),clock_source.clock()),same,&mut owner))));assert!(tag.is_some());assert!(!owner.as_ref().unwrap().captured());assert_eq!(emit.artifact_mutations.as_ptr(),input);assert_eq!(caller.cx().retained_progress(),before);
   let exact=RetainedCloneGrant{maximum_capacity_bytes:quote.capacity_bytes,..unit};assert!(actor_admission_turn(caller.cx(),|cx|cx.with_retained_loan(exact,|same|OriginalTypingSettlement::<A>::admit(index as u64+1,&base,&metadata.actor,&mut emit,0,||(tag.take().unwrap(),clock_source.clock()),same,&mut owner))));let actual=caller.cx().retained_progress().retained_capacity_bytes-before.retained_capacity_bytes;assert_eq!(actual,quote.capacity_bytes);assert_eq!(quote.capacity_bytes,metadata.actor.len()+frame);
   println!("sdk-actor-admission={}",serde_json::json!({"name":"typing","cancelled":cancel,"index":index,"actor":metadata.actor,"baselineCapacity":0,"frameCapacity":frame,"quotedCapacity":quote.capacity_bytes,"actualCapacity":actual,"deniedUnchanged":true,"sharedFrameQuoted":true,"oneItem":true}));
   let mut born=None;for _ in 0..1_048_576{if owner.as_ref().is_some_and(|value|value.captured()){break}caller.cx().with_retained_loan(unit,|same|OriginalTypingSettlement::<A>::admit(index as u64+1,&base,&metadata.actor,&mut emit,0,||(tag.take().unwrap(),clock_source.clock()),same,&mut owner)).unwrap();if let Some(value)=owner.as_ref(){let pointer=&**value as*const _;if let Some(original)=born{assert_eq!(pointer,original)}else{born=Some(pointer)}}if !owner.as_ref().unwrap().captured(){assert!(tag.is_some());assert_eq!(emit.artifact_mutations.as_ptr(),input);}}assert!(owner.as_ref().unwrap().captured());assert!(tag.is_none());assert!(emit.artifact_mutations.is_empty());let address=&**owner.as_ref().unwrap()as*const _;let receipt=caller.cx().retained_progress();
   caller.cx().with_retained_loan(Default::default(),|same|owner.as_mut().unwrap().advance(&mut ledger,index as u64+1,&base,&metadata.actor,&mut emit,same)).unwrap();assert_eq!(caller.cx().retained_progress(),receipt);assert!(!owner.as_ref().unwrap().received());
   if index==1&&cancel{caller.cx().with_retained_loan(unit,|same|owner.as_mut().unwrap().advance(&mut ledger,2,&base,&metadata.actor,&mut emit,same)).unwrap();caller.cx().original_source_parent().unwrap().cancellation().unwrap().cancel_now();}
   else{for _ in 0..1_048_576{if owner.as_ref().unwrap().received(){break}caller.cx().with_retained_loan(unit,|same|owner.as_mut().unwrap().advance(&mut ledger,index as u64+1,&base,&metadata.actor,&mut emit,same)).unwrap();assert_eq!(&**owner.as_ref().unwrap()as*const _,address);}assert!(owner.as_ref().unwrap().received());}
   for _ in 0..1_048_576{if owner.as_ref().unwrap().terminal_is_empty(){break}caller.cx().with_original_retirement(|same|owner.as_mut().unwrap().close_step(&mut ledger,same)).unwrap();}assert!(owner.as_ref().unwrap().terminal_is_empty());
   if index==0{assert!(emit.artifact_mutations.is_empty());assert!(emit.transaction.is_none());previous_pointer=pointer;let LayoutMutation::RenameLayout(value)=&ledger.open(WINDOW).unwrap().net[0]else{unreachable!()};assert_eq!(value.new_name.as_ptr(),pointer);}
   else if cancel{assert!(!owner.as_ref().unwrap().received());let LayoutMutation::RenameLayout(value)=&ledger.open(WINDOW).unwrap().net[0]else{unreachable!()};assert_eq!(value.new_name,"Typing First");assert_eq!(value.new_name.as_ptr(),previous_pointer);assert!(emit.transaction.is_none());}
   else{let LayoutMutation::RenameLayout(value)=&emit.artifact_mutations[0]else{unreachable!()};assert_eq!(value.new_name,"Typing First");assert_eq!(value.new_name.as_ptr(),previous_pointer);assert!(emit.transaction.is_some());let LayoutMutation::RenameLayout(value)=&ledger.open(WINDOW).unwrap().net[0]else{unreachable!()};assert_eq!(value.new_name,"Typing Second");assert_eq!(value.new_name.as_ptr(),pointer);}
   let demand=owner.as_ref().unwrap().shell_close_demands();caller.cx().with_original_retirement(|same|close_original_retained_step(same,demand,|_|{owner.take();Ok(semio_framework_value::RetainedCloneStep::Complete(semio_framework_value::RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,released_bytes:demand.release_bytes,..Default::default()}))})).unwrap();
   let mut emitted=ControlledRetirement::retain(emit);for _ in 0..1_048_576{if emitted.terminal_is_empty(){break}let demand=emitted.next_demand(caller.cx().retained_grant().maximum_copy_bytes).unwrap();caller.cx().with_original_retirement(|same|close_original_retained_step(same,demand,|g|emitted.step(g))).unwrap();}assert!(emitted.terminal_is_empty());
  }
  while !ledger.original_windows_terminal_is_empty(){let mut row:Option<TypingState<LayoutMutation>>=None;let mut key:Option<SharedUtf8>=None;let demand=ledger.original_close_window_demands().unwrap();caller.cx().with_original_retirement(|same|close_original_retained_step(same,demand,|g|ledger.close_original_window(&mut row,&mut key,g).map(semio_framework_value::RetainedCloneStep::Progress))).unwrap();let mut fields=ControlledRetirement::retain((row,key));for _ in 0..1_048_576{if fields.terminal_is_empty(){break}let demand=fields.next_demand(caller.cx().retained_grant().maximum_copy_bytes).unwrap();caller.cx().with_original_retirement(|same|close_original_retained_step(same,demand,|g|fields.step(g))).unwrap();}assert!(fields.terminal_is_empty());}
  assert_eq!(caller.cx().original_recipient_identity(),original_source);assert_eq!(caller.cx().native_receiving_identity(),original_decoder);
  println!("original-typing-edit-custody={}",serde_json::json!({"cancelled":cancel,"oneItemTurns":true,"sameOwner":true,"originalLeafPointer":true,"priorRetainedOrPublished":true,"closed":ledger.original_windows_terminal_is_empty()}));caller.retire();
 }
}
